import React, { useState } from 'react';
import VideoPlayer from './components/VideoPlayer';
import Chat from './components/Chat';
import './styles.css';

const App = () => {
  const [url, setUrl] = useState('');
  const [videoId, setVideoId] = useState('');
  const [chatId, setChatId] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    const videoId = extractVideoId(url);
    const chatId = extractChatId(url);
    setVideoId(videoId);
    setChatId(chatId);
  };

  const extractVideoId = (url) => {
    // Implement the logic to extract video ID from the URL
    const urlParams = new URLSearchParams(new URL(url).search);
    return urlParams.get('v'); // Example for YouTube video ID
  };

  const extractChatId = (url) => {
    // Implement the logic to extract chat ID from the URL if needed
    return 'some-chat-id'; // Placeholder
  };

  return (
    <div className="app-container">
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          placeholder="Enter video URL"
          className="url-input"
        />
        <button type="submit">Load Video</button>
      </form>
      {videoId && <VideoPlayer videoId={videoId} />}
      {chatId && <Chat chatId={chatId} />}
    </div>
  );
};

export default App;
